int fd_file; // Existing open file descriptor
mode_t new_perms = 0750; // rwxr-x---

// Change permissions using the file descriptor
int status = fchmod(fd_file, new_perms);

if (status == -1) {
    // Common Errors:
    // EBADF: Invalid file descriptor.
    // EPERM: Caller lacks permission (not owner/root).
    // EROFS: Read-only file system.
    return errno;
}

// Success: Permissions changed for the file
// associated with fd_file.
